import http from 'node:http';
export async function fixtureServer(){const requests=[];const server=http.createServer(async(req,res)=>{let raw='';for await(const chunk of req)raw+=chunk;const body=raw?JSON.parse(raw):null;requests.push({url:req.url,authorization:req.headers.authorization,body});res.setHeader('Content-Type','application/json');if(!req.url.startsWith('/v1/')){res.writeHead(404);return res.end('{}');}if(req.headers.authorization==='Bearer denied-401'||req.headers.authorization==='Bearer denied-403'){const status=req.headers.authorization.endsWith('401')?401:403;res.writeHead(status);return res.end(JSON.stringify({error:{message:'fixture rejected '+req.headers.authorization}}));}if(req.url==='/v1/models')return res.end(JSON.stringify({data:[{id:'text-fixture'},{id:'vision-fixture'},{id:'text-fixture'}]}));if(req.url==='/v1/chat/completions'){if(body.stream){res.setHeader('Content-Type','text/event-stream');return res.end('data: '+JSON.stringify({choices:[{delta:{content:'附件分析完成（测试服务）'}}]})+'\n\ndata: '+JSON.stringify({choices:[],usage:{prompt_tokens:12,completion_tokens:6,total_tokens:18}})+'\n\ndata: [DONE]\n\n');}return res.end(JSON.stringify({model:body.model,choices:[{message:{role:'assistant',content:'OK'}}]}));}res.writeHead(404);res.end('{}');});await new Promise(r=>server.listen(0,'127.0.0.1',r));return {requests,baseUrl:`http://127.0.0.1:${server.address().port}`,close:()=>new Promise(r=>server.close(r))};}
